class Solution:
    def groupAnagrams(self, strs: list[str]) -> list[list[str]]:
        n = len(strs)
        visited = [False] * n
        res = []
        def is_anagram(a: str, b: str) -> bool:
            if len(a) != len(b):
                return False
            freq = [0] * 26
            for ch in a:
                freq[ord(ch) - 97] += 1
            for ch in b:
                freq[ord(ch) - 97] -= 1
            return all(x == 0 for x in freq)
        for i in range(n):
            if visited[i]:
                continue
            group = [strs[i]]
            visited[i] = True
            for j in range(i + 1, n):
                if not visited[j] and is_anagram(strs[i], strs[j]):
                    group.append(strs[j])
                    visited[j] = True
            res.append(group)
        return res

